"""Format-independent dataset fingerprints, Merkle commitments and Ed25519 signed manifests.

Canonicalisation makes the digest identical for the same logical table stored as CSV or Parquet:
numerics (int/float/bool) -> float64 bits (-0.0 and NaN normalised; ints beyond 2**53 keep int64 bits),
datetimes -> UTC int64 ns, everything else -> 128-bit BLAKE2b of the UTF-8 text.
"""
from __future__ import annotations

import hashlib
import json
from datetime import datetime, timezone

import numpy as np
import pandas as pd

from . import __version__
from .keys import KeyBundle, verify_signature

CHUNK_ROWS = 1024
_NAN_BITS = np.float64(np.nan).view(np.uint64)


def _is_dt(s: pd.Series) -> bool:
    return pd.api.types.is_datetime64_any_dtype(s)


def column_class(s: pd.Series) -> str:
    if _is_dt(s):
        return "datetime"
    if pd.api.types.is_bool_dtype(s) or pd.api.types.is_numeric_dtype(s):
        return "number"
    return "text"


def _hash16(text: str) -> tuple[int, int]:
    d = hashlib.blake2b(text.encode("utf-8"), digest_size=16).digest()
    return int.from_bytes(d[:8], "little"), int.from_bytes(d[8:], "little")


def column_words(s: pd.Series) -> np.ndarray:
    """-> uint64 array (n, w): canonical encoding of every cell."""
    cls = column_class(s)
    if cls == "datetime":
        t = pd.to_datetime(s, utc=True).dt.as_unit("ns")   # pandas>=3 may hold us/ms units
        v = t.astype("int64").to_numpy().astype(np.int64)
        v = np.where(t.isna().to_numpy(), np.iinfo(np.int64).min, v)
        return v.view(np.uint64).reshape(-1, 1)
    if cls == "number":
        if pd.api.types.is_integer_dtype(s) and not s.isna().any():
            a = s.to_numpy(dtype=np.int64)
            if np.abs(a).max(initial=0) >= 2 ** 53:
                return np.stack([a.view(np.uint64), np.full(a.shape, 1, np.uint64)], axis=1)
        f = pd.to_numeric(s, errors="coerce").to_numpy(dtype=np.float64, na_value=np.nan)
        f = f + 0.0  # -0.0 -> 0.0
        w = f.view(np.uint64).copy()
        w[np.isnan(f)] = _NAN_BITS
        return w.reshape(-1, 1)
    codes, uniq = pd.factorize(s.astype(object).where(s.notna(), None), use_na_sentinel=True)
    table = np.zeros((len(uniq) + 1, 2), dtype=np.uint64)
    table[0] = _hash16("\x00NULL")
    for i, u in enumerate(uniq):
        table[i + 1] = _hash16("\x01" + str(u))
    return table[codes + 1]


def row_hashes(df: pd.DataFrame, columns: list[str] | None = None) -> list[bytes]:
    cols = columns if columns is not None else list(df.columns)
    if not cols or len(df) == 0:
        return []
    m = np.ascontiguousarray(np.concatenate([column_words(df[c]) for c in cols], axis=1))
    b = hashlib.blake2b
    return [b(m[i].tobytes(), digest_size=32).digest() for i in range(m.shape[0])]


def _merkle(leaves: list[bytes]) -> bytes:
    if not leaves:
        return hashlib.sha256(b"provenmark/empty").digest()
    level = leaves
    while len(level) > 1:
        nxt = [hashlib.sha256(b"\x01" + level[i] + (level[i + 1] if i + 1 < len(level) else level[i])).digest()
               for i in range(0, len(level), 2)]
        level = nxt
    return level[0]


def fingerprint(df: pd.DataFrame, chunk_rows: int = CHUNK_ROWS) -> dict:
    cols = list(df.columns)
    rh = row_hashes(df)
    chunks = [hashlib.sha256(b"\x00" + b"".join(rh[i:i + chunk_rows])).digest()
              for i in range(0, len(rh), chunk_rows)]
    col_dig = {}
    for c in cols:
        col_dig[c] = hashlib.sha256(np.ascontiguousarray(column_words(df[c])).tobytes()).hexdigest()
    return {
        "rows": int(len(df)),
        "columns": [{"name": str(c), "class": column_class(df[c])} for c in cols],
        "chunk_rows": chunk_rows,
        "merkle_root": _merkle(chunks).hex(),
        "chunk_hashes": [c.hex() for c in chunks] if len(chunks) <= 65536 else None,
        "column_digests": {str(k): v for k, v in col_dig.items()},
    }


def canonical_json(obj) -> bytes:
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()


def seal(df: pd.DataFrame, keys: KeyBundle, name: str = "", extra: dict | None = None) -> dict:
    """Sign the *original* dataset. Returns a self-contained signed manifest."""
    manifest = {
        "format": "provenmark.manifest/1", "tool": f"provenmark {__version__}",
        "name": name, "created": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "dataset": fingerprint(df), "extra": extra or {},
    }
    return {"manifest": manifest,
            "signature": {"alg": "ed25519", "public_key": keys.public_key.hex(), "key_id": keys.key_id,
                          "sig": keys.sign(canonical_json(manifest)).hex()}}


def verify_manifest_signature(signed: dict, public_key: bytes | None = None) -> bool:
    sig = signed["signature"]
    pk = bytes.fromhex(sig["public_key"])
    if public_key is not None and pk != public_key:
        return False
    return verify_signature(pk, canonical_json(signed["manifest"]), bytes.fromhex(sig["sig"]))


def verify(df: pd.DataFrame, signed: dict, public_key: bytes | None = None) -> dict:
    """Check signature, then locate differences (columns, row chunks) if the data was altered."""
    sig_ok = verify_manifest_signature(signed, public_key)
    ref = signed["manifest"]["dataset"]
    cur = fingerprint(df, ref["chunk_rows"])
    # signer_pinned False: the signature was checked against the key embedded in the manifest only (self-signed is
    # possible); callers that need to know WHO signed must pass the expected public key
    res = {"signature_valid": sig_ok, "signer_pinned": public_key is not None,
           "identical": sig_ok and cur["merkle_root"] == ref["merkle_root"],
           "rows": {"expected": ref["rows"], "actual": cur["rows"]}}
    if not res["identical"]:
        ref_cols = {c["name"] for c in ref["columns"]}
        cur_cols = {c["name"] for c in cur["columns"]}
        res["columns_missing"] = sorted(ref_cols - cur_cols)
        res["columns_added"] = sorted(cur_cols - ref_cols)
        res["columns_modified"] = sorted(c for c in ref_cols & cur_cols
                                         if ref["column_digests"][c] != cur["column_digests"][c])
        if ref.get("chunk_hashes") and cur.get("chunk_hashes"):
            rc, cc = ref["chunk_hashes"], cur["chunk_hashes"]
            bad = [i for i in range(min(len(rc), len(cc))) if rc[i] != cc[i]]
            k = ref["chunk_rows"]
            res["modified_row_ranges"] = [[i * k, min((i + 1) * k, ref["rows"]) - 1] for i in bad][:200]
    return res


# ---- keyed row index: detect verbatim copies / subsets / reshuffles / format conversions ---------------
def row_index(df: pd.DataFrame, key: bytes, columns: list[str] | None = None) -> np.ndarray:
    """Sorted array of 64-bit keyed row tags. Useless without the key (no dictionary attack on rows)."""
    cols = columns if columns is not None else list(df.columns)
    tags = np.fromiter((int.from_bytes(hashlib.blake2b(h, key=key, digest_size=8).digest(), "little")
                        for h in row_hashes(df, cols)), dtype=np.uint64, count=len(df))
    return np.unique(tags)


def scan_overlap(suspect: pd.DataFrame, index: np.ndarray, key: bytes, columns: list[str]) -> dict:
    if not all(c in suspect.columns for c in columns):
        return {"rows": len(suspect), "matched": 0, "fraction": 0.0, "note": "columns missing"}
    tags = row_index(suspect, key, columns)
    matched = int(np.isin(tags, index, assume_unique=True).sum())
    # per-row false-match probability ~ |index| / 2**64
    return {"rows": int(len(suspect)), "unique_rows": int(len(tags)), "matched": matched,
            "fraction": matched / max(len(tags), 1), "false_match_prob_per_row": len(index) / 2.0 ** 64}
